widget.solution:
def seconds_by_op(log):
    totals, counts = {}, {}
    for question, op, seconds, right in log:
        totals[op] = totals.get(op, 0) + seconds
        counts[op] = counts.get(op, 0) + 1
    return {op: totals[op] / counts[op] for op in totals}


def slowest(log):
    means = seconds_by_op(log)
    return max(means, key=means.get)
